 useEffect(()=>{if(!popover)return;const closeOnOutside=e=>{if(!e.target.closest('.popover-anchor'))setPopover(null)};document.addEventListener('pointerdown',closeOnOutside);return()=>document.removeEventListener('pointerdown',closeOnOutside)},[popover])
