function ImageListGallery({notify}){
 const [selected,setSelected]=useState(0);const [menu,setMenu]=useState(null)
 const items=[['夏日气泡水主视觉','清爽蓝绿色调，适用于新品发布首页。','1:1 · PNG · 2.4 MB','visual-a'],['沙丘品牌情绪图','温暖自然光与柔和沙色的品牌氛围。','3:4 · JPG · 3.1 MB','visual-b'],['产品发布横幅','适用于官网首屏和社交媒体封面。','4:3 · PNG · 4.8 MB','visual-c']]
 return <section className="image-list-section"><header><div><span>LIST / IMAGE</span><h2>图片布局列表</h2></div><p>用于素材库、生成结果和媒体资源选择。</p></header><div className="image-layout-list">{items.map(([title,desc,meta,visual],i)=><article className={selected===i?'selected':''} key={title}><button className={`image-list-preview ${visual}`} onClick={()=>{setSelected(i);notify(`已选择${title}`)}} aria-label={`选择${title}`}><i/><i/></button><button className="image-list-copy" onClick={()=>{setSelected(i);notify(`已打开${title}`)}}><b>{title}</b><p>{desc}</p><small><Image/>{meta}</small></button><div className="image-list-end"><em>{selected===i?<><Check/>已选择</>:`方案 ${i+1}`}</em><button aria-label="更多操作" onClick={()=>setMenu(menu===i?null:i)}><MoreHorizontal/></button>{menu===i&&<div className="image-list-menu"><button onClick={()=>{notify('图片已预览');setMenu(null)}}><Eye/>预览</button><button onClick={()=>{notify('图片已下载');setMenu(null)}}><Download/>下载</button><button className="delete" onClick={()=>{notify('图片已移除');setMenu(null)}}><Trash2/>移除</button></div>}</div></article>)}</div><footer><b>图片列表标准</b><span>缩略图 120 × 90px · 比例 4:3 · 行间距 8px · 内容间距 16px · 支持选中与操作菜单</span></footer></section>
}

function ImageLayoutPatterns({notify}){
 const [gridColumns,setGridColumns]=useState(4);const [masonryColumns,setMasonryColumns]=useState(4);const visuals=['visual-a','visual-b','visual-c','visual-d'];const imageNames=['清爽主视觉','沙丘情绪图','薄荷产品图','午夜发布图']
 return <section className="image-pattern-section"><header><div><span>IMAGE / LAYOUT</span><h2>图片内容布局</h2></div><p>针对浏览、选择、预览和方案比较的常用图片结构。</p></header><div className="image-pattern-stack">
  <article className="image-pattern-block"><header><div><b>卡片网格</b><small>适合素材库、模板和作品集合</small></div><ColumnControl value={gridColumns} onChange={setGridColumns}/></header><div className="image-card-grid" style={{'--image-columns':gridColumns}}>{Array.from({length:8},(_,i)=>{const visual=visuals[i%4];return <button onClick={()=>notify(`已打开图片方案 ${i+1}`)} key={i}><span className={visual}><i/><i/></span><b>{imageNames[i%4]}</b><small>方案 {i+1} · 4:3</small></button>})}</div></article>
  <article className="image-pattern-block"><header><div><b>瀑布流</b><small>适合不同宽高比的图片内容</small></div><ColumnControl value={masonryColumns} onChange={setMasonryColumns}/></header><div className="image-masonry" style={{'--image-columns':masonryColumns}}>{[['visual-a','3:4'],['visual-b','1:1'],['visual-c','4:5'],['visual-d','4:3'],['visual-b','3:4'],['visual-a','1:1'],['visual-d','4:5'],['visual-c','4:3']].map(([visual,ratio],i)=><button className={`masonry-${ratio.replace(':','-')}`} onClick={()=>notify(`已选择瀑布流图片 ${i+1}`)} key={`${visual}-${i}`}><span className={visual}><i/><i/></span><em>{ratio}</em></button>)}</div></article>
 </div><footer><b>选型建议</b><span>批量浏览使用卡片网格 · 不同比例内容使用瀑布流 · 大量素材使用横向媒体流</span></footer></section>
}

function ColumnControl({value,onChange}){return <div className="column-control" aria-label="选择列数"><span>列数</span>{[4,6,8].map(x=><button className={value===x?'active':''} onClick={()=>onChange(x)} key={x}>{x}</button>)}</div>}

function TablePatternGallery({notify}){
 const rows=[
  {id:1,name:'Prompt 输入',type:'Agent 组件',owner:'Nano Banana',status:'已发布',updated:'今天 10:45'},
  {id:2,name:'Prompt 输出',type:'Agent 组件',owner:'ShuLan Agent',status:'审核中',updated:'昨天 16:20'},
  {id:3,name:'Popover',type:'交互组件',owner:'Mona',status:'草稿',updated:'昨天 09:12'},
  {id:4,name:'数据表格',type:'基础组件',owner:'Nano Banana',status:'已发布',updated:'8月28日'},
  {id:5,name:'任务列表',type:'基础组件',owner:'ShuLan Agent',status:'已停用',updated:'8月26日'}
 ]
 const [query,setQuery]=useState('');const [selected,setSelected]=useState([]);const [ascending,setAscending]=useState(true);const [density,setDensity]=useState('舒适');const [page,setPage]=useState(1)
 const filtered=rows.filter(x=>(x.name+x.type+x.owner+x.status).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(ascending?1:-1)*a.name.localeCompare(b.name))
 const toggle=id=>setSelected(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id]);const all=filtered.length>0&&filtered.every(x=>selected.includes(x.id))
 return <section className="table-pattern-section"><header><div><span>TABLE / STANDARD</span><h2>表格样式标准</h2></div><p>用于结构化数据浏览、选择、比较和批量操作。</p></header><div className="table-toolbar"><label><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索名称、类型或负责人"/>{query&&<button onClick={()=>setQuery('')}><X/></button>}</label><button className="secondary"><Filter/>筛选</button><div className="density-control">{['紧凑','舒适'].map(x=><button className={density===x?'active':''} onClick={()=>setDensity(x)} key={x}>{x}</button>)}</div>{selected.length>0&&<button className="primary" onClick={()=>{notify(`已批量处理 ${selected.length} 项`);setSelected([])}}>批量操作 · {selected.length}</button>}</div><div className={`standard-table density-${density==='紧凑'?'compact':'comfortable'}`}><div className="table-row table-head"><div><button className={`table-check ${all?'checked':''}`} onClick={()=>setSelected(all?[]:filtered.map(x=>x.id))}>{all&&<Check/>}</button></div><button onClick={()=>setAscending(!ascending)}>名称 <ArrowUpDown/></button><span>类型</span><span>负责人</span><span>状态</span><span>更新时间</span><span>操作</span></div>{filtered.map(row=><div className={`table-row ${selected.includes(row.id)?'selected':''}`} key={row.id}><div data-label="选择"><button className={`table-check ${selected.includes(row.id)?'checked':''}`} onClick={()=>toggle(row.id)}>{selected.includes(row.id)&&<Check/>}</button></div><div data-label="名称"><b>{row.name}</b><small>#{String(row.id).padStart(3,'0')}</small></div><span data-label="类型">{row.type}</span><span data-label="负责人"><i className="table-avatar">{row.owner[0]}</i>{row.owner}</span><span data-label="状态"><em className={`table-status status-${row.status}`}>{row.status}</em></span><time data-label="更新时间">{row.updated}</time><div className="table-actions" data-label="操作"><button onClick={()=>notify(`正在查看 ${row.name}`)}><Eye/></button><button onClick={()=>notify(`正在编辑 ${row.name}`)}><Pencil/></button><button onClick={()=>notify(`${row.name} 的更多操作已打开`)}><MoreHorizontal/></button></div></div>)}{!filtered.length&&<div className="table-empty"><Search/><b>没有匹配的数据</b><p>尝试修改搜索关键词或清除筛选条件。</p><button className="secondary" onClick={()=>setQuery('')}>清除搜索</button></div>}</div><footer className="table-footer"><span>共 {filtered.length} 条记录 · 已选择 {selected.length} 条</span><div><button disabled={page===1} onClick={()=>setPage(1)}>上一页</button><button className="active">{page}</button><button onClick={()=>setPage(2)}>2</button><button disabled={page===2} onClick={()=>setPage(2)}>下一页</button></div></footer><div className="table-state-grid"><TableState title="加载状态" icon={<span className="spinner"/>} text="正在同步数据，请稍候…"/><TableState title="空数据状态" icon={<Inbox/>} text="暂无记录，可创建第一条数据。"/><TableState title="错误状态" icon={<CircleHelp/>} text="数据加载失败，请稍后重试。" action={<button onClick={()=>notify('正在重新加载表格')}><RefreshCw/>重新加载</button>}/></div><div className="table-standard-note"><b>统一标准</b><span>表头 44px · 舒适行 64px · 紧凑行 48px · 单元格横向 16px · 表格圆角 16px · 主文字 14px · 辅助文字 12px</span></div></section>
}

function TableState({title,icon,text,action}){return <article><i>{icon}</i><div><b>{title}</b><p>{text}</p></div>{action}</article>}

function PlacementPopoverDemo({notify}){
 const [placement,setPlacement]=useState('top')
 const [open,setOpen]=useState(true)
 useEffect(()=>{if(!open)return;const closeOnOutside=e=>{if(!e.target.closest('.placement-anchor')&&!e.target.closest('.placement-controls'))setOpen(false)};document.addEventListener('pointerdown',closeOnOutside);return()=>document.removeEventListener('pointerdown',closeOnOutside)},[open])
 const positions=[['top-start','左上'],['top','上方'],['top-end','右上'],['right','右侧'],['bottom-end','右下'],['bottom','下方'],['bottom-start','左下'],['left','左侧']]
 return <section className="placement-section"><header><div><span>PLACEMENT</span><h2>气泡浮层位置</h2></div><p>选择位置，观察浮层相对于触发目标的锚定方向。</p></header><div className="placement-controls">{positions.map(([id,label])=><button className={placement===id?'active':''} onClick={()=>{setPlacement(id);setOpen(true);notify(`Popover 已切换至${label}`)}} key={id}>{label}</button>)}</div><div className="placement-canvas"><div className="placement-anchor"><button className="primary" onClick={()=>setOpen(!open)}><Sparkles/>触发目标</button>{open&&<div className={`placement-bubble place-${placement}`}><b>{positions.find(x=>x[0]===placement)?.[1]}浮层</b><p>Popover 会根据所选位置贴近触发目标展示。</p><button onClick={()=>notify('浮层操作已触发')}>执行操作</button></div>}</div></div></section>
}

function PopoverContent({type,onClose,notify}){
 const [choice,setChoice]=useState('Opus 4.6')
 if(type==='menu')return <div className="demo-popover menu-popover"><button onClick={()=>{notify('已复制链接');onClose()}}><Copy/>复制链接</button><button onClick={()=>{notify('已加入收藏');onClose()}}><Sparkles/>加入收藏</button><button className="danger-row" onClick={()=>{notify('记录已删除');onClose()}}><Trash2/>删除记录</button></div>
 if(type==='select')return <div className="demo-popover select-popover"><small>选择模型</small>{['Opus 4.6','Sonnet 4.5','ShuLan 快速版'].map(x=><button className={choice===x?'selected':''} onClick={()=>{setChoice(x);notify(`已选择 ${x}`)}} key={x}><span>{x}</span>{choice===x&&<Check/>}</button>)}</div>
 if(type==='image')return <div className="demo-popover image-popover"><button className="popover-x" aria-label="关闭图片预览" onClick={onClose}><X/></button><div className="popover-image-preview"><i/><i/></div><div className="popover-image-meta"><span><b>夏日主视觉</b><small>1024 × 1024 · PNG</small></span><button onClick={()=>{notify('图片大图已打开');onClose()}}><Maximize2/>查看大图</button></div></div>
 if(type==='profile')return <div className="demo-popover profile-popover"><button className="popover-x" onClick={onClose}><X/></button><span className="big-avatar nova">N</span><div><b>Nano Banana</b><small><i/>在线 · Team plan</small></div><button className="secondary" onClick={()=>{notify('成员资料已打开');onClose()}}>查看资料</button></div>
 if(type==='confirm')return <div className="demo-popover confirm-popover"><b>删除这条记录？</b><p>删除后无法恢复。</p><footer><button className="secondary" onClick={onClose}>取消</button><button className="danger" onClick={()=>{notify('记录已删除');onClose()}}>删除</button></footer></div>
 if(type==='loading')return <div className="demo-popover loading-popover"><span className="spinner"/><div><b>正在载入内容</b><small>请稍候，数据即将显示…</small></div></div>
 return <div className="demo-popover info-popover"><button className="popover-x" onClick={onClose}><X/></button><CircleHelp/><div><b>智能操作提示</b><p>你可以通过快捷命令继续完成当前任务。</p><button onClick={()=>{notify('帮助文档已打开');onClose()}}>查看帮助</button></div></div>
}

function ReleasePopup({title,text,art,compact,onClose,onLearn}){return <article className={`release-popup ${compact?'is-compact':''}`} role="dialog" aria-modal="true">{!compact&&<div className={`release-art ${art||''}`}><i/><i/><i/></div>}<button className="prototype-close" aria-label="关闭" onClick={onClose}><X/></button><div><h3>{title}</h3><p>{text}</p><footer><button className="secondary" onClick={onClose}>稍后</button><button className="primary" onClick={onLearn}>了解更多</button></footer></div></article>}

function PrototypeNotice({media,onClose,onLearn}){return <article className={`prototype-notice ${media?'has-media':''}`} role="status"><header><span><CircleHelp/>通知</span><button aria-label="关闭通知" onClick={onClose}><X/></button></header><div><p>浏览器扩展仍处于测试阶段，可能存在未知风险。请保持警惕并保护账户安全。</p>{media&&<div className="notice-visual"><i/><i/></div>}</div>{media&&<button className="primary" onClick={onLearn}>了解更多</button>}</article>}

function Modal({onClose,onCreate}){const ref=useRef();const [name,setName]=useState('');const [type,setType]=useState('基础组件');const [typesOpen,setTypesOpen]=useState(false);useLayoutEffect(()=>{gsap.fromTo(ref.current,{opacity:0,scale:.94,y:18},{opacity:1,scale:1,y:0,duration:.35,ease:'back.out(1.6)'})},[]);return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" ref={ref} onSubmit={e=>{e.preventDefault();if(name.trim()){onCreate(name.trim());onClose()}}}><div className="modal-icon"><Sparkles/></div><button type="button" className="modal-close" onClick={onClose}><X/></button><h2>创建新组件</h2><p>从模板开始，快速搭建适合 Agent 工作流的组件。</p><label>组件名称<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="例如：Task Card"/></label><label>组件类型<div className="select" tabIndex="0" onClick={()=>setTypesOpen(!typesOpen)}><Component/>{type}<ChevronDown/></div>{typesOpen&&<div className="type-menu">{['基础组件','Agent 组件','布局组件'].map(x=><button type="button" onClick={()=>{setType(x);setTypesOpen(false)}} key={x}>{x}{x===type&&<Check/>}</button>)}</div>}</label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>取消</button><button className="primary" disabled={!name.trim()}>创建组件</button></div></form></div>}

function CommandPalette({onClose,onSelect}){const [query,setQuery]=useState('');const results=demoSections.filter(x=>(x.title+x.eyebrow+x.desc).toLowerCase().includes(query.toLowerCase()));return <div className="modal-backdrop command-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="command-palette"><div className="command-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索组件、基础和 Agent 模式…"/><kbd>ESC</kbd></div><small>快速跳转</small><div className="command-results">{results.map(x=><button onClick={()=>onSelect(x.id)} key={x.id}><Component/><span><b>{x.title}</b><small>{x.eyebrow}</small></span><span>跳转</span></button>)}{!results.length&&<div className="empty"><Search/><p>没有找到相关组件</p></div>}</div><footer><span><kbd>↵</kbd> 打开</span><span><kbd>esc</kbd> 关闭</span></footer></div></div>}

function Notifications({onClose,notify}){const [items,setItems]=useState(['Prompt 组件已完成构建','Nano Banana 提及了你','设计令牌已同步']);return <div className="notifications popover"><header><b>通知</b><button onClick={()=>{setItems([]);notify('已全部标记为已读')}}>全部已读</button></header>{items.length?items.map((x,i)=><button className="notice-row" onClick={()=>{setItems(items.filter((_,n)=>n!==i));notify(x)}} key={x}><span className={`agent-avatar ${['mint','nova','flare'][i]}`}><Inbox/></span><span><b>{x}</b><small>{i===0?'刚刚':`${i+1} 小时前`}</small></span><i/></button>):<div className="empty"><CheckCircle2/><p>没有新通知</p></div>}<button className="notice-footer" onClick={onClose}>关闭</button></div>}

function ApiDrawer({section,onClose,notify}){const code=`<ShuLan${section.title.replace(/\s/g,'')}\n  variant="primary"\n  size="default"\n  disabled={false}\n/>`;return <div className="drawer-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><aside className="api-drawer"><header><div><small>COMPONENT API</small><h2>{section.title}</h2></div><button className="icon-btn" onClick={onClose}><X/></button></header><p>{section.desc}</p><h3>Props</h3>{[['variant','primary | secondary'],['size','tiny | small | default | large'],['disabled','boolean'],['onClick','() => void']].map(x=><div className="prop-row" key={x[0]}><code>{x[0]}</code><span>{x[1]}</span></div>)}<h3>使用示例</h3><pre>{code}</pre><button className="secondary copy-code" onClick={()=>{navigator.clipboard?.writeText(code);notify('示例代码已复制')}}><Copy/>复制代码</button></aside></div>}

function PromptImageOutput({notify}){const [selected,setSelected]=useState(0);const [ratio,setRatio]=useState('1:1');const [generating,setGenerating]=useState(false);const images=[['暮光城市','image-a'],['薄荷空间','image-b'],['珊瑚地貌','image-c'],['午夜产品','image-d']];const generate=()=>{setGenerating(true);setTimeout(()=>{setGenerating(false);notify('已生成 4 张新图片')},1500)};return <div className="media-output image-output"><div className="media-header"><div><span className="agent-avatar flare"><Image/></span><div><b>ShuLan 图片生成器</b><small>{generating?'正在生成候选图片…':'已完成 · 4 个候选结果'}</small></div></div><div className="format-control">{['1:1','4:3','16:9'].map(x=><button className={ratio===x?'active':''} onClick={()=>setRatio(x)} key={x}>{x}</button>)}</div></div><div className="media-prompt"><Sparkles/><div><small>生成提示词</small><p>未来主义产品摄影，柔和的薄荷绿光线，极简空间，细腻材质，高级商业视觉。</p></div><button onClick={()=>notify('提示词已复制')}><Copy/>复制</button></div>{generating?<div className="generation-loading"><span className="spinner"/><b>正在生成图片</b><p>正在渲染光影、材质和构图…</p></div>:<><div className={`image-results ratio-${ratio.replace(':','-')}`}>{images.map(([name,cls],i)=><button className={`generated-image ${cls} ${selected===i?'selected':''}`} onClick={()=>setSelected(i)} key={name}><span>{selected===i?<Check/>:i+1}</span><b>{name}</b></button>)}</div><div className="media-actions"><div><span>已选择：<b>{images[selected][0]}</b></span><button className="secondary" onClick={()=>notify('已打开图片编辑器')}><SlidersHorizontal/>继续编辑</button></div><button className="secondary" onClick={generate}><RotateCcw/>重新生成</button><button className="primary" onClick={()=>notify(`${images[selected][0]} 已下载`)}><Download/>下载图片</button></div></>}</div>}

function PromptVideoOutput({notify}){const [playing,setPlaying]=useState(false);const [progress,setProgress]=useState(38);const [variant,setVariant]=useState(0);const [generating,setGenerating]=useState(false);const generate=()=>{setGenerating(true);setTimeout(()=>{setGenerating(false);setProgress(0);notify('新的视频版本已生成')},1600)};return <div className="media-output video-output"><div className="media-header"><div><span className="agent-avatar flare"><GalleryHorizontalEnd/></span><div><b>ShuLan 视频生成器</b><small>{generating?'正在生成视频…':'已完成 · 1080P · 8 秒'}</small></div></div><div className="video-variants">{['版本 1','版本 2','版本 3'].map((x,i)=><button className={variant===i?'active':''} onClick={()=>setVariant(i)} key={x}>{x}</button>)}</div></div><div className="media-prompt"><Sparkles/><div><small>视频提示词</small><p>镜头缓慢推进，展示透明气泡水瓶，背景光线由蓝色过渡到紫色，液体气泡自然上升。</p></div><button onClick={()=>notify('视频提示词已复制')}><Copy/>复制</button></div>{generating?<div className="generation-loading video-loading"><span className="spinner"/><b>正在合成视频</b><p>生成关键帧并处理镜头运动…</p></div>:<><div className={`video-canvas video-version-${variant}`}><div className="video-scene"><span className="product-bottle"/><i/><i/><i/></div><button className="play-button" onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><button className="fullscreen" onClick={()=>notify('已进入全屏预览')}><Maximize2/></button><div className="video-timeline"><button onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><span>00:0{Math.round(progress/13)} / 00:08</span><div onClick={e=>setProgress(Math.round(e.nativeEvent.offsetX/e.currentTarget.clientWidth*100))}><i style={{width:`${progress}%`}}/></div><b>1080P</b></div></div><div className="shot-list"><div><span>01</span><div><b>产品入场</b><small>0:00 — 0:02</small></div><i/></div><div><span>02</span><div><b>光线过渡</b><small>0:02 — 0:05</small></div><i/></div><div><span>03</span><div><b>品牌定格</b><small>0:05 — 0:08</small></div><i/></div></div><div className="media-actions"><div><span>当前版本：<b>版本 {variant+1}</b></span><button className="secondary" onClick={()=>notify('已打开视频编辑器')}><SlidersHorizontal/>编辑镜头</button></div><button className="secondary" onClick={generate}><RotateCcw/>重新生成</button><button className="primary" onClick={()=>notify('视频已导出')}><Download/>导出视频</button></div></>}</div>}

function PromptOutputHub({notify}){const [format,setFormat]=useState('text');const formats=[['text',MessageSquareText,'文本输出','气泡信息流与结构化文本'],['image',Image,'图片生成','候选图片与编辑操作'],['video',GalleryHorizontalEnd,'视频生成','播放器、镜头与导出']];return <div className="output-hub"><div className="output-format-tabs">{formats.map(([id,Icon,title,desc])=><button className={format===id?'active':''} onClick={()=>setFormat(id)} key={id}><Icon/><span><b>{title}</b><small>{desc}</small></span>{format===id&&<Check/>}</button>)}</div><div className="output-format-content" key={format}>{format==='text'?<PromptOutput notify={notify}/>:format==='image'?<PromptImageOutput notify={notify}/>:<PromptVideoOutput notify={notify}/>}</div></div>}

function UnifiedPromptOutput({notify}){const [selectedImage,setSelectedImage]=useState(0);const [playing,setPlaying]=useState(false);const [input,setInput]=useState('');const [sending,setSending]=useState(false);const [followups,setFollowups]=useState([]);const imageOptions=[['image-a','1:1'],['image-b','3:4'],['image-c','4:3']];const send=()=>{if(sending){setSending(false);notify('已停止生成');return}const value=input.trim();if(!value){notify('请输入追问内容');return}setFollowups(x=>[...x,{role:'user',text:value}]);setInput('');setSending(true);setTimeout(()=>{setFollowups(x=>[...x,{role:'agent',text:'我会继续结合上面的文本、图片和视频结果进行处理，并保持相同的视觉方向。'}]);setSending(false)},1200)};return <div className="unified-feed"><div className="stream-header"><div><span className="agent-avatar flare"><Bot/></span><div><b>ShuLan Agent</b><small>多模态创作助手</small></div></div><span className="complete"><Check/>已连接</span></div><div className="unified-flow"><div className="message-row user-row"><div className="bubble user-bubble">为新品气泡水设计一套发布内容，包括文案、主视觉和短视频。</div><span className="agent-avatar nova">N</span></div><div className="message-row agent-row"><span className="agent-avatar flare"><Bot/></span><div><div className="bubble agent-bubble"><span className="message-type"><MessageSquareText/>文本输出</span><p>我会围绕“轻盈、清爽、充满活力”的主题完成整套发布内容。核心文案建议为：</p><blockquote>打开这一刻，让清爽气泡点亮整个夏天。</blockquote><p>下面是根据该方向生成的主视觉候选方案。</p></div><MessageFeedback text="打开这一刻，让清爽气泡点亮整个夏天。" notify={notify}/></div></div><div className="message-row agent-row"><span className="agent-avatar flare"><Image/></span><div className="bubble agent-bubble media-bubble image-message"><div className="media-message-head"><span className="message-type"><Image/>图片生成输出</span><small>已生成 3 张 · 多比例</small></div><div className="inline-image-grid">{imageOptions.map(([cls,ratio],i)=><div className={`image-option ratio-${ratio.replace(':','-')}`} key={cls}><button className={`${cls} ${selectedImage===i?'selected':''}`} onClick={()=>setSelectedImage(i)} aria-label={`选择 ${ratio} 图片方案`}><span>{selectedImage===i?<Check/>:i+1}</span></button><small>Aspect Ratio <i>/</i> <b>{ratio}</b></small></div>)}</div><div className="inline-media-actions"><span>已选择方案 {selectedImage+1} · {imageOptions[selectedImage][1]}</span><button onClick={()=>notify('已打开图片编辑器')}><SlidersHorizontal/>继续编辑</button><button onClick={()=>notify('图片已下载')}><Download/>下载</button></div></div></div><div className="message-row agent-row"><span className="agent-avatar flare"><GalleryHorizontalEnd/></span><div className="bubble agent-bubble media-bubble video-message"><div className="media-message-head"><span className="message-type"><GalleryHorizontalEnd/>视频生成输出</span><small>1080P · 8 秒</small></div><div className="inline-video"><div className="video-scene"><span className="product-bottle"/><i/><i/><i/></div><button className="play-button" onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><div className="inline-video-bar"><button onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><span>00:03 / 00:08</span><i><b/></i><button onClick={()=>notify('已进入全屏预览')}><Maximize2/></button></div></div><div className="inline-media-actions"><span>版本 1 · 品牌氛围短片</span><button onClick={()=>notify('已打开视频编辑器')}><SlidersHorizontal/>编辑镜头</button><button onClick={()=>notify('视频已导出')}><Download/>导出</button></div></div></div>{followups.map((m,i)=>m.role==='user'?<div className="message-row user-row" key={i}><div className="bubble user-bubble">{m.text}</div><span className="agent-avatar nova">N</span></div>:<div className="message-row agent-row" key={i}><span className="agent-avatar flare"><Bot/></span><div className="bubble agent-bubble"><span className="message-type"><MessageSquareText/>文本输出</span><p>{m.text}</p></div></div>)}{sending&&<div className="message-row agent-row"><span className="agent-avatar flare"><Bot/></span><div className="bubble agent-bubble typing"><i/><i/><i/><span>正在生成多模态回复…</span></div></div>}</div><div className="output-composer unified-composer"><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')send()}} placeholder="继续追问，或输入新的创作任务…"/><div><span><kbd>⌘</kbd><kbd>Enter</kbd> 发送</span><button className="icon-btn" onClick={()=>notify('附件选择器已打开')}><Paperclip/></button><button className={`send ${sending?'stop':''}`} onClick={send}>{sending?<Square/>:<ArrowUp/>}</button></div></div></div>}

function MessageFeedback({text,notify}){return <div className="message-tools"><button onClick={()=>{navigator.clipboard?.writeText(text);notify('文本已复制')}}><Copy/>复制</button><button onClick={()=>notify('已标记为有帮助')}><Check/>有帮助</button></div>}

createRoot(document.getElementById('root')).render(<App />)
